-- The Profession Trainers added in 4.0.3 (Runda in Razor Hill, Nedric Sallow, Lalum Darkmane, Iranis Shadebloom and
-- Jack "All-Trades" Derrington) teach the apprentice level of every primary profession. They had no trainer spells,
-- so no option did anything, and their main menu listed "Train me in ..." options without an action. The trainer
-- option on each profession page now opens the shared apprentice list.
UPDATE `creature_template` SET `trainer_type` = 2 WHERE `entry` IN (47400, 47418, 47419, 47420, 50247);
UPDATE `creature_template` SET `npcflag` = 81 WHERE `entry` = 50247;
UPDATE `creature_template` SET `gossip_menu_id` = 12180 WHERE `entry` = 47419;

DELETE FROM `gossip_menu_option` WHERE `MenuID` BETWEEN 12180 AND 12199 AND `OptionType` = 0
    AND `OptionText` LIKE 'Train me in %';

DELETE FROM `npc_trainer` WHERE `entry` IN (47400, 47418, 47419, 47420, 50247, 201010);
